const tol = 1e-12;

const eta = [1, -1, -1, -1];
const qUp = [2.1, -0.7, 1.3, 0.4];
const qDown = qUp.map((x, i) => eta[i] * x);
const q2 = qUp.reduce((s, x, i) => s + eta[i] * x * x, 0);
const I2 = -7.8867;

// The unique conserved symmetric rank-two structure generated by one momentum.
const transverse = Array.from({ length: 4 }, (_, mu) =>
  Array.from({ length: 4 }, (_, nu) =>
    qDown[mu] * qDown[nu] - q2 * (mu === nu ? eta[mu] : 0)
  )
);
const oddSpurionKernel = transverse.map((row) => row.map((x) => I2 * x));

const ward = Array.from({ length: 4 }, (_, nu) =>
  qUp.reduce((s, qmu, mu) => s + qmu * oddSpurionKernel[mu][nu], 0)
);
const symmetricFailure = Math.max(
  ...oddSpurionKernel.flatMap((row, mu) =>
    row.map((x, nu) => Math.abs(x - oddSpurionKernel[nu][mu]))
  )
);

const maxWardFailure = Math.max(...ward.map(Math.abs));
const kernelNorm = Math.sqrt(
  oddSpurionKernel.flat().reduce((s, x) => s + x * x, 0)
);

const parityLedger = {
  stressTensor: +1,
  cpOddSpurionI2: -1,
  cpOddResponseOperator: -1,
  productI2TimesResponse: +1,
};

const passed =
  maxWardFailure < tol &&
  symmetricFailure < tol &&
  kernelNorm > tol &&
  parityLedger.cpOddSpurionI2 * parityLedger.cpOddResponseOperator ===
    parityLedger.productI2TimesResponse;

console.log(
  JSON.stringify(
    {
      protocol: "cp-odd-spurion-stress-two-point-reopening/1",
      qUp,
      q2,
      I2,
      tensor: "I2 (q_mu q_nu - q^2 eta_mu_nu)",
      maxWardFailure,
      symmetricFailure,
      kernelNorm,
      parityLedger,
      interpretation:
        "A CP-odd scalar spurion conditionally supplies the odd background absent from the no-spurion vacuum theorem; it does not construct the Furey-to-spacetime parity intertwiner.",
      passed,
    },
    null,
    2
  )
);

if (!passed) process.exitCode = 1;
